import * as THREE from 'three/webgpu';
import { texture as textureNode } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Set position, rotation, scale
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load brushed metal texture
  const metalMap = ctx.textureLoader.load(config.assets.imageUrl);

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Create material using TSL nodes
  const colorNode = textureNode(metalMap);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: colorNode,
  });

  // Create and add plane mesh
  const plane = new THREE.Mesh(geometry, material);
  group.add(plane);

  // Render text content via font atlas
  if (config.textContent && ctx.fontAtlas) {
    const textMesh = ctx.fontAtlas.create(config.textContent, {
      fontSize: 0.34,
      fontWeight: 400,
      fontFamily: 'display',
      color: '#e8ecf2',
      align: 'center',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Setup cleanup
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    metalMap.dispose();
  };

  return group;
}
